solutionCodeJson.code:
.page {
  display: grid;
  min-height: 100vh;
  grid-template-areas:
    "header header"
    "sidebar main"
    "footer footer";
  grid-template-columns: 220px 1fr;
  grid-template-rows: auto 1fr auto;
}

.site-header {
  grid-area: header;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: #1f2937;
  color: #fff;
  padding: 16px 32px;
}

.logo {
  color: #fff;
  text-decoration: none;
  font-weight: bold;
  font-size: 20px;
}

.top-nav {
  display: flex;
  gap: 20px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.top-nav a {
  color: #fff;
  text-decoration: none;
}

.sidebar {
  grid-area: sidebar;
  background: #f3f4f6;
  padding: 24px;
}

.sidebar-nav {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.sidebar-nav a {
  text-decoration: none;
  color: #1f2937;
}

.main-content {
  grid-area: main;
  padding: 24px;
}

.card-row {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
}

.summary-card {
  flex: 1 1 160px;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  padding: 16px;
}

.site-footer {
  grid-area: footer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: #1f2937;
  color: #fff;
  padding: 16px 32px;
}

.footer-links {
  display: flex;
  gap: 16px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.footer-links a {
  color: #fff;
  text-decoration: none;
}
